INSERT INTO purpose VALUES('surface-lsp-diagnostics','','crate','The diagnostics of the language server: the recheck of a document, the kernel tiers, the repairs and fills of a hole, a model''s proposals and the checkpoints a save keeps.',NULL,'fits','sound',NULL);
